html:
{# إشعار إحالة — Murasalat Referral notification handed to the recipient.

   Arabic-first on purpose (see the correspondence format). The parent correspondence is
   read through a permission check so a print never exposes a file the printing user
   cannot open; a restricted parent prints as مقيّد.
#}
{% set DIRECTION_AR = {"Incoming": "وارد", "Outgoing": "صادر", "Internal": "داخلي"} %}
{% set RECIPIENT_TYPE_AR = {"User": "مستخدم", "Department": "قسم"} %}
{% set can_read_parent = frappe.has_permission("Murasalat Correspondence", doc=doc.correspondence, ptype="read") %}
{% set parent_subject = frappe.db.get_value("Murasalat Correspondence", doc.correspondence, "subject") if (can_read_parent and doc.correspondence) else None %}
{% set parent_body = frappe.db.get_value("Murasalat Correspondence", doc.correspondence, "notes") if (can_read_parent and doc.correspondence) else None %}
{% set parent_direction = frappe.db.get_value("Murasalat Correspondence", doc.correspondence, "correspondence_direction") if (can_read_parent and doc.correspondence) else None %}
{% set today = frappe.utils.getdate(frappe.utils.today()) %}
{% set due = frappe.utils.getdate(doc.due_date) if doc.due_date else None %}
{% set days_left = (due - today).days if due else None %}
<style>
  @page { size: A4; margin: 12mm; }

  .mo-print {
    direction: rtl;
    text-align: right;
    font-family: "Noto Naskh Arabic", "Amiri", "Traditional Arabic", "Segoe UI", Tahoma, Arial, sans-serif;
    color: #17231f;
    font-size: 10.5pt;
    line-height: 1.75;
  }
  .mo-print .head { width: 100%; border-collapse: collapse; border-bottom: 2.2pt solid #123c35; }
  .mo-print .head td { border: none; vertical-align: bottom; padding: 0 0 2mm 0; }
  .mo-print .title { font-size: 15pt; font-weight: bold; color: #123c35; }
  .mo-print .subtitle { font-size: 9.5pt; color: #55655f; }
  .mo-print .doc-no { direction: ltr; text-align: left; font-size: 13pt; font-weight: bold; color: #123c35; letter-spacing: 0.4pt; }
  .mo-print .badges { margin: 3mm 0 4mm 0; }
  .mo-print .badge {
    display: inline-block; border: 0.9pt solid #123c35; border-radius: 2pt;
    padding: 0.6mm 2.6mm; margin-left: 2mm; font-size: 9pt; font-weight: bold;
  }
  .mo-print .badge.plain { border-color: #8fa39c; color: #3c4a45; font-weight: normal; }
  .mo-print .badge.alert { border-color: #b03a2e; color: #b03a2e; background: #fdf3f1; }
  .mo-print .badge.private { border-color: #6b1f18; color: #6b1f18; background: #f7e9e7; }
  .mo-print table.grid { width: 100%; border-collapse: collapse; margin: 0 0 4mm 0; }
  .mo-print table.grid th {
    background: #eef3f1; color: #123c35; text-align: right; font-size: 9.4pt;
    border: 0.6pt solid #c9d8d3; padding: 1.6mm 2mm; font-weight: bold;
  }
  .mo-print table.grid td { border: 0.6pt solid #c9d8d3; padding: 1.6mm 2mm; vertical-align: top; }
  .mo-print table.meta td.label { background: #f6f9f8; width: 22%; font-size: 9.2pt; color: #3c4a45; }
  .mo-print table.meta td.value { width: 28%; font-weight: bold; }
  .mo-print .mono { direction: ltr; text-align: left; font-family: "DejaVu Sans Mono", Consolas, monospace; font-size: 8.2pt; }
  .mo-print .section-title {
    font-size: 11pt; font-weight: bold; color: #123c35; margin: 4mm 0 1.5mm 0;
    border-right: 3pt solid #2f6b5f; padding-right: 2mm;
  }
  .mo-print .to-box { border: 1.2pt solid #123c35; padding: 3mm 3.5mm; margin-bottom: 4mm; }
  .mo-print .to-box .role { font-size: 9pt; color: #55655f; }
  .mo-print .to-box .who { font-size: 12.5pt; font-weight: bold; }
  .mo-print .instr { border: 0.6pt solid #c9d8d3; background: #fbfdfc; padding: 3.5mm; min-height: 22mm; white-space: pre-wrap; }
  .mo-print .body-excerpt { border: 0.6pt solid #c9d8d3; background: #f8faf9; padding: 3mm 3.5mm; white-space: pre-wrap; font-size: 9.6pt; }
  .mo-print .cut { margin-top: 6mm; border-top: 1pt dashed #8fa39c; padding-top: 2mm; font-size: 8.6pt; color: #55655f; }
  .mo-print table.sign { width: 100%; border-collapse: separate; border-spacing: 2.5mm 0; margin-top: 2mm; }
  .mo-print table.sign td { border: 0.6pt solid #c9d8d3; padding: 2mm; vertical-align: top; width: 33.3%; }
  .mo-print .sign-role { font-size: 9pt; color: #3c4a45; font-weight: bold; }
  .mo-print .sign-space { height: 14mm; }
  .mo-print .sign-line { border-top: 0.6pt solid #8fa39c; font-size: 8.4pt; color: #55655f; padding-top: 1mm; }
  .mo-print .foot { margin-top: 5mm; border-top: 0.6pt solid #c9d8d3; padding-top: 1.5mm; font-size: 8.2pt; color: #55655f; }
  .mo-print .muted { color: #7b8b86; }
</style>

<div class="mo-print" dir="rtl">

  <table class="head">
    <tr>
      <td>
        <div class="title">إشعار إحالة</div>
        <div class="subtitle">يُسلَّم إلى الجهة أو الموظف المختص ويُعاد موقّعًا</div>
      </td>
      <td class="doc-no">{{ doc.referral_number or doc.name }}</td>
    </tr>
  </table>

  <div class="badges">
    {% if doc.private_referral %}<span class="badge private">خاص</span>{% endif %}
    {% if days_left is not none and days_left < 0 %}<span class="badge alert">متأخرة {{ -days_left }} يومًا</span>
    {% elif days_left == 0 %}<span class="badge alert">تستحق اليوم</span>
    {% elif days_left is not none and days_left <= 2 %}<span class="badge alert">تستحق خلال {{ days_left }} يوم</span>{% endif %}
    {% if doc.importance %}<span class="badge plain">{{ doc.importance }}</span>{% endif %}
    {% if doc.follow_up %}<span class="badge plain">للمتابعة</span>{% endif %}
    {% if doc.paper_copy %}<span class="badge plain">نسخة ورقية</span>{% endif %}
    {% if doc.cc_copy %}<span class="badge plain">صورة للعلم</span>{% endif %}
  </div>

  <div class="to-box">
    <div class="role">الموجَّه إليه — {{ RECIPIENT_TYPE_AR.get(doc.recipient_type, doc.recipient_type) }}</div>
    <div class="who">{{ doc.recipient_user or doc.recipient_department or "—" }}</div>
  </div>

  <table class="grid meta">
    <tr>
      <td class="label">رقم الإحالة</td>
      <td class="value">{{ doc.referral_number or doc.name }}</td>
      <td class="label">المعاملة المرجعية</td>
      <td class="value">{{ doc.correspondence or "—" }}</td>
    </tr>
    <tr>
      <td class="label">موضوع المعاملة</td>
      <td class="value" colspan="3">
        {% if parent_subject %}{{ parent_subject }}
        {% elif doc.correspondence %}<span class="muted">مقيّد — لا تملك صلاحية قراءة هذه المعاملة</span>
        {% else %}—{% endif %}
      </td>
    </tr>
    <tr>
      <td class="label">اتجاه الإحالة</td>
      <td class="value">{{ doc.direction or "—" }}</td>
      <td class="label">اتجاه المعاملة</td>
      <td class="value">{{ DIRECTION_AR.get(parent_direction, parent_direction) if parent_direction else "—" }}</td>
    </tr>
    <tr>
      <td class="label">تاريخ الإرسال</td>
      <td class="value">{{ frappe.utils.get_datetime(doc.sent_on).strftime("%d-%m-%Y %H:%M") if doc.sent_on else "—" }}</td>
      <td class="label">الموعد النهائي</td>
      <td class="value">{{ due.strftime("%d-%m-%Y") if due else "—" }}</td>
    </tr>
    {% if doc.received_on %}
    <tr>
      <td class="label">تاريخ الاستلام</td>
      <td class="value">{{ frappe.utils.get_datetime(doc.received_on).strftime("%d-%m-%Y %H:%M") }}</td>
      <td class="label">استلمها</td>
      <td class="value">{{ doc.received_by or "—" }}</td>
    </tr>
    {% endif %}
    {% if doc.completed_on %}
    <tr>
      <td class="label">تاريخ الإكمال</td>
      <td class="value">{{ frappe.utils.get_datetime(doc.completed_on).strftime("%d-%m-%Y %H:%M") }}</td>
      <td class="label">أكملها</td>
      <td class="value">{{ doc.completed_by or "—" }}</td>
    </tr>
    {% endif %}
  </table>

  <div class="section-title">التعليمات إلى المستلِم</div>
  <div class="instr">{{ doc.instructions or "—" }}</div>

  {% if can_read_parent and parent_body %}
  <div class="section-title">مضمون المعاملة (للعلم)</div>
  <div class="body-excerpt">{{ parent_body }}</div>
  {% endif %}

  <table class="sign">
    <tr>
      <td>
        <div class="sign-role">توقيع المُرسِل / الجهة المُحيلة</div>
        <div class="sign-space"></div>
        <div class="sign-line">الاسم والتوقيع والتاريخ</div>
      </td>
      <td>
        <div class="sign-role">إقرار المستلِم بالاستلام</div>
        <div class="sign-space"></div>
        <div class="sign-line">الاسم والتوقيع والتاريخ</div>
      </td>
      <td>
        <div class="sign-role">ملاحظات المستلِم</div>
        <div class="sign-space"></div>
        <div class="sign-line">ما تم إنجازه / ما يلزم</div>
      </td>
    </tr>
  </table>

  <div class="cut">
    قُصّ هنا وأعِد الشريط الموقّع إلى مكتب المراسلات — الإحالة {{ doc.referral_number or doc.name }}
    {% if doc.correspondence %} المعاملة {{ doc.correspondence }}{% endif %}
  </div>

  <div class="foot">
    طُبع بواسطة {{ frappe.session.user }} — {{ frappe.utils.get_datetime(frappe.utils.now()).strftime("%d-%m-%Y %H:%M") }}
    {% if doc.workflow_state %} · الحالة: {{ doc.workflow_state }}{% endif %}
  </div>

</div>
